const Q = forSubject("DOC");
type Anchor = "regle" | "exemple" | "erreur" | "approfondir";
function dq(
  set: string,
  id: string,
  skill: string,
  family: string,
  difficulty: 1 | 2 | 3,
  stem: string,
  opts: Opt[],
  explanation: string,
  rule: string,
  hints: [string, string, string],
  anchor: Anchor = "regle",
  reserved = false,
) {
  return Q(id, skill, family, difficulty, stem, opts, explanation, rule, {
    documentSet: set,
    timeSec: 360,
    hints,
    lessonAnchor: anchor,
    ...(reserved ? { reserved: true } : {}),
  });
}

